function normalizeRank(rank) {
  return String(rank ?? "").trim().toUpperCase();
}
function normalizeSuit(suit) {
  const value = String(suit ?? "").trim().toLowerCase();
  if (value.includes("heart") || value.includes("\u05DC\u05D1")) return "hearts";
  if (value.includes("diamond") || value.includes("\u05D9\u05D4\u05DC")) return "diamonds";
  if (value.includes("club") || value.includes("\u05EA\u05DC\u05EA")) return "clubs";
  if (value.includes("spade") || value.includes("\u05E2\u05DC\u05D9") || value.includes("\u05E2\u05DC\u05D4")) {
    return "spades";
  }
  return value;
}
function suitLetterFromKey(suit) {
  if (suit === "hearts") return "H";
  if (suit === "diamonds") return "D";
  if (suit === "clubs") return "C";
  if (suit === "spades") return "S";
  return "";
}
function getCardKnowledgeId(card) {
  const rank = normalizeRank(card?.rank?.key);
  const suit = normalizeSuit(card?.suit?.key);
  return `${rank}${suitLetterFromKey(suit)}`;
}
function getCardKnowledge(card) {
  const id = getCardKnowledgeId(card);
  return CARD_KNOWLEDGE_MAP[id] ?? null;
}
function getExtendedCardKnowledge(card) {
  const id = getCardKnowledgeId(card);
  return CARD_KNOWLEDGE_MAP[id] ?? null;
}
function getCardMeaning(card) {
  const knowledge = getCardKnowledge(card);
  if (knowledge?.cardMeaning) return knowledge.cardMeaning;
  const rank = normalizeRank(card?.rank?.key);
  const suit = normalizeSuit(card?.suit?.key);
  const numberMeaning = NUMBER_MEANINGS[rank]?.general ?? "\u05DE\u05E1\u05E8 \u05DB\u05DC\u05DC\u05D9";
  const suitMeaning = SUIT_MEANINGS[suit]?.general ?? "\u05EA\u05D7\u05D5\u05DD \u05DB\u05DC\u05DC\u05D9";
  return `${numberMeaning} \u05D1\u05EA\u05D7\u05D5\u05DD \u05E9\u05DC ${suitMeaning}`;
}
function getPersonMeaning(card) {
  const knowledge = getCardKnowledge(card);
  const rank = normalizeRank(card?.rank?.key);
  const suit = normalizeSuit(card?.suit?.key);
  if (knowledge?.personMeaning) return knowledge.personMeaning;
  if (rank === "J" || rank === "Q" || rank === "K") {
    return SUIT_MEANINGS[suit]?.personTone ?? "\u05D0\u05D3\u05DD \u05DE\u05E9\u05DE\u05E2\u05D5\u05EA\u05D9";
  }
  return "";
}
function getCardKeywords(card) {
  const knowledge = getCardKnowledge(card);
  return knowledge?.keywords ?? [];
}
function getSuitMeaningByTopic(suit, topic) {
  const suitKey = normalizeSuit(suit);
  const meaning = SUIT_MEANINGS[suitKey];
  if (!meaning) return "\u05EA\u05D7\u05D5\u05DD \u05DB\u05DC\u05DC\u05D9";
  if (topic === "love") return meaning.love;
  if (topic === "work") return meaning.work;
  if (topic === "money") return meaning.money;
  if (topic === "health") return meaning.health;
  return meaning.general;
}
function buildPositionedMeaning(card, position, topic) {
  const label = POSITION_LABELS[position] || position;
  const knowledge = getCardKnowledge(card);
  if (knowledge) {
    return `${label}: ${knowledge.cardMeaning}.`;
  }
  const rank = normalizeRank(card?.rank?.key);
  const suit = normalizeSuit(card?.suit?.key);
  const numberMeaning = NUMBER_MEANINGS[rank]?.general ?? "\u05DE\u05E1\u05E8 \u05D7\u05E9\u05D5\u05D1";
  const suitMeaning = getSuitMeaningByTopic(suit, topic);
  return `${label}: ${numberMeaning} \u05D1\u05EA\u05D7\u05D5\u05DD \u05E9\u05DC ${suitMeaning}.`;
}
function buildSimpleTiming(cards) {
  const highCards = cards.filter(
    (c) => c.rank.num >= 9 || c.rank.key === "10" || c.rank.key === "K"
  ).length;
  const lowCards = cards.filter((c) => c.rank.num <= 4).length;
  const hasEight = cards.some((c) => c.rank.key === "8");
  const hasFourSpades = cards.some(
    (c) => c.rank.key === "4" && normalizeSuit(c.suit.key) === "spades"
  );
  if (hasFourSpades) {
    return "\u05D9\u05E9 \u05E1\u05D9\u05DE\u05DF \u05DC\u05E2\u05D9\u05DB\u05D5\u05D1 \u05D6\u05DE\u05E0\u05D9, \u05D5\u05DC\u05DB\u05DF \u05D4\u05D3\u05D1\u05E8\u05D9\u05DD \u05D0\u05D9\u05E0\u05DD \u05DE\u05D9\u05D9\u05D3\u05D9\u05D9\u05DD.";
  }
  if (highCards >= 2) {
    return "\u05D4\u05D3\u05D1\u05E8\u05D9\u05DD \u05DE\u05EA\u05E7\u05E8\u05D1\u05D9\u05DD \u05DC\u05E9\u05DC\u05D1 \u05E1\u05D9\u05D5\u05DD \u05D0\u05D5 \u05EA\u05D5\u05E6\u05D0\u05D4 \u05D1\u05E7\u05E8\u05D5\u05D1.";
  }
  if (hasEight) {
    return "\u05E0\u05E8\u05D0\u05D9\u05EA \u05EA\u05E0\u05D5\u05E2\u05D4, \u05D5\u05DC\u05DB\u05DF \u05D4\u05D4\u05EA\u05E4\u05EA\u05D7\u05D5\u05EA \u05E2\u05E9\u05D5\u05D9\u05D4 \u05DC\u05D4\u05D9\u05D5\u05EA \u05DE\u05D4\u05D9\u05E8\u05D4 \u05D9\u05D7\u05E1\u05D9\u05EA.";
  }
  if (lowCards >= 2) {
    return "\u05DE\u05D3\u05D5\u05D1\u05E8 \u05D1\u05E9\u05DC\u05D1 \u05DE\u05D5\u05E7\u05D3\u05DD \u05D9\u05D7\u05E1\u05D9\u05EA, \u05D5\u05DC\u05DB\u05DF \u05E0\u05D3\u05E8\u05E9 \u05E2\u05D5\u05D3 \u05D6\u05DE\u05DF \u05DC\u05D4\u05EA\u05E4\u05EA\u05D7\u05D5\u05EA.";
  }
  return "\u05D4\u05EA\u05D4\u05DC\u05D9\u05DA \u05E2\u05D3\u05D9\u05D9\u05DF \u05DE\u05EA\u05E4\u05EA\u05D7 \u05D1\u05D4\u05D3\u05E8\u05D2\u05D4.";
}
function collectPeople(cards) {
  return cards.map((card) => getPersonMeaning(card)).filter((value) => Boolean(value));
}
function detectDominantSuit(cards) {
  const count = {};
  cards.forEach((c) => {
    const suit = normalizeSuit(c?.suit?.key);
    count[suit] = (count[suit] || 0) + 1;
  });
  const sorted = Object.entries(count).sort((a, b) => b[1] - a[1]);
  return sorted[0]?.[0] || "none";
}
function detectTopicFromQuestion(question) {
  const q = question.toLowerCase();
  if (q.includes("\u05D0\u05D4\u05D1\u05D4") || q.includes("\u05D6\u05D5\u05D2\u05D9\u05D5\u05EA") || q.includes("\u05E7\u05E9\u05E8")) {
    return "love";
  }
  if (q.includes("\u05E2\u05D1\u05D5\u05D3\u05D4") || q.includes("\u05E7\u05E8\u05D9\u05D9\u05E8\u05D4") || q.includes("\u05DE\u05E9\u05E8\u05D4")) {
    return "work";
  }
  if (q.includes("\u05DB\u05E1\u05E3") || q.includes("\u05E4\u05E8\u05E0\u05E1\u05D4") || q.includes("\u05D4\u05DB\u05E0\u05E1\u05D4")) {
    return "money";
  }
  if (q.includes("\u05D1\u05E8\u05D9\u05D0\u05D5\u05EA") || q.includes("\u05E8\u05E4\u05D5\u05D0\u05D4") || q.includes("\u05D2\u05D5\u05E3")) {
    return "health";
  }
  return "general";
}
